// Copied from Root Word (Cross Word Puzzle repo), where it is generated by
// scripts/generateLpkSplashHtml.js from the animation template and the LPK
// Apps logo. Do not edit by hand: regenerate there and copy it here, so
// every LPK Apps title plays the identical intro.
export const LPK_SPLASH_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; background: #18181a; overflow: hidden; }\n  canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }\n</style>\n</head>\n<body>\n<canvas id=\"cv\"></canvas>\n<script>window.LOGO_SRC=\"data:image/jpeg;base64,\";</script>\n<script>\n(function () {\n  var cv = document.getElementById('cv');\n  var ctx = cv.getContext('2d');\n  var W = 0, H = 0, DPR = 1;\n\n  function resize() {\n    DPR = Math.min(window.devicePixelRatio || 1, 3);\n    W = window.innerWidth; H = window.innerHeight;\n    cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);\n    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  }\n  resize();\n\n  // ---- timing (ms) ----\n  var FADE_IN = 450;   // logo fade-in\n  var HOLD    = 500;   // hold before the shimmer\n  var SHIMMER = 560;   // shooting-star glint travels up the logo\n  var TWINKLE = 320;   // sparkle + fade-out at the top\n  var ONSET   = 800;   // dissolve edge climbs the icon\n  var WORD_FADE = 450; // wordmark fades out as the melt starts\n  var MELT_MS = 5000;  // safety cap on total melt time\n\n  // ---- drip tuning ----\n  var STEP = 5, DARK_CUT = 44, GRAVITY_MIN = 1500, GRAVITY_VAR = 600, DRIP_WIDTH = 5, TRAIL_MAX = 150;\n\n  // icon artwork ends / wordmark begins at this fraction of logo height\n  var SPLIT = 0.585;\n  // edge feather: fully opaque inside FEATHER_IN x logo width, gone by FEATHER_OUT\n  var FEATHER_IN = 0.46, FEATHER_OUT = 0.70;\n\n  var LOGO = 0, LX = 0, LY = 0, SPLIT_PX = 0;\n  function layout() {\n    LOGO = Math.round(Math.min(W * 0.62, H * 0.36, 320));\n    LX = Math.round((W - LOGO) / 2);\n    LY = Math.round((H - LOGO) / 2);\n    SPLIT_PX = Math.round(LOGO * SPLIT);\n  }\n  layout();\n\n  var img = new Image();\n  var iconCv = null, wordCv = null;\n  var template = [], parts = [];\n  var phase = 'in', t0 = 0, holdAt = 0, shimmerAt = 0, meltAt = 0, last = 0, raf = null, finished = false;\n\n  // Pre-render the logo at device resolution with feathered edges — the JPEG's\n  // baked-in background is a hair lighter than the page bg, so a hard square\n  // edge shows on dark screens. Split into icon (melts) and wordmark (fades).\n  function buildLayers() {\n    var wpx = LOGO * DPR;\n    var off = document.createElement('canvas'); off.width = wpx; off.height = wpx;\n    var o = off.getContext('2d');\n    o.drawImage(img, 0, 0, wpx, wpx);\n    var g = o.createRadialGradient(wpx / 2, wpx / 2, wpx * FEATHER_IN, wpx / 2, wpx / 2, wpx * FEATHER_OUT);\n    g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,1)');\n    o.globalCompositeOperation = 'destination-out';\n    o.fillStyle = g; o.fillRect(0, 0, wpx, wpx);\n\n    var sy = Math.round(SPLIT_PX * DPR);\n    iconCv = document.createElement('canvas'); iconCv.width = wpx; iconCv.height = sy;\n    iconCv.getContext('2d').drawImage(off, 0, 0, wpx, sy, 0, 0, wpx, sy);\n    wordCv = document.createElement('canvas'); wordCv.width = wpx; wordCv.height = wpx - sy;\n    wordCv.getContext('2d').drawImage(off, 0, sy, wpx, wpx - sy, 0, 0, wpx, wpx - sy);\n  }\n\n  function drawIcon(alpha) {\n    if (alpha <= 0) return;\n    ctx.globalAlpha = alpha;\n    ctx.drawImage(iconCv, 0, 0, iconCv.width, iconCv.height, LX, LY, LOGO, SPLIT_PX);\n    ctx.globalAlpha = 1;\n  }\n  function drawWord(alpha) {\n    if (alpha <= 0) return;\n    ctx.globalAlpha = alpha;\n    ctx.drawImage(wordCv, 0, 0, wordCv.width, wordCv.height, LX, LY + SPLIT_PX, LOGO, LOGO - SPLIT_PX);\n    ctx.globalAlpha = 1;\n  }\n\n  function sampleLogo() {\n    var off = document.createElement('canvas'); off.width = LOGO; off.height = LOGO;\n    var o = off.getContext('2d'); o.drawImage(img, 0, 0, LOGO, LOGO);\n    var d = o.getImageData(0, 0, LOGO, LOGO).data; template = [];\n    for (var y = 0; y < SPLIT_PX; y += STEP) {   // icon only — the wordmark fades, it doesn't melt\n      for (var x = 0; x < LOGO; x += STEP) {\n        var i = (y * LOGO + x) * 4; var al = d[i + 3]; if (al < 128) continue;\n        var r = d[i], g = d[i + 1], b = d[i + 2]; if ((r + g + b) / 3 < DARK_CUT) continue;\n        template.push({ x: LX + x, y: LY + y, color: 'rgb(' + r + ',' + g + ',' + b + ')' });\n      }\n    }\n  }\n\n  function spawnDrips() {\n    parts = template.map(function (p) {\n      return {\n        x: p.x, y: p.y, color: p.color,\n        vx: (Math.random() - 0.5) * 14, vy: 0,\n        g: GRAVITY_MIN + Math.random() * GRAVITY_VAR,\n        delay: (ONSET / 1000) * ((LY + SPLIT_PX - p.y) / SPLIT_PX) + Math.random() * 0.12\n      };\n    });\n  }\n\n  function finish() {\n    if (finished) return; finished = true;\n    try {\n      if (window.ReactNativeWebView) { window.ReactNativeWebView.postMessage('lpk-splash-done'); }\n      else { parent.postMessage('lpk-splash-done', '*'); }\n    } catch (e) {}\n  }\n\n  function frame(now) {\n    var dt = Math.min(0.05, (now - last) / 1000); last = now;\n    ctx.clearRect(0, 0, W, H);\n\n    if (phase === 'in') {\n      var a = Math.min(1, (now - t0) / FADE_IN);\n      drawIcon(a); drawWord(a);\n      if (a >= 1) { phase = 'hold'; holdAt = now; }\n\n    } else if (phase === 'hold') {\n      drawIcon(1); drawWord(1);\n      if (now - holdAt >= HOLD) { phase = 'shimmer'; shimmerAt = now; }\n\n    } else if (phase === 'shimmer') {\n      drawIcon(1); drawWord(1);\n\n      var te = now - shimmerAt;\n      var traveling = te <= SHIMMER;\n      var sp = Math.min(1, te / SHIMMER);\n      var e = sp * sp * sp * (sp * (sp * 6 - 15) + 10);          // smootherstep\n      var fadeIn = Math.sin(Math.min(1, sp / 0.10) * Math.PI / 2);\n      var twk = traveling ? 0 : Math.min(1, (te - SHIMMER) / TWINKLE);\n\n      var P0 = { x: LX + LOGO * 0.50, y: LY + LOGO - 4 };\n      var P1 = { x: LX + LOGO * 1.05, y: LY + LOGO * 0.72 };\n      var P2 = { x: LX + LOGO * 1.03, y: LY + LOGO * 0.16 };\n      var P3 = { x: LX + LOGO * 0.54, y: LY + 2 };\n      function bez(t) {\n        var u = 1 - t, a = u*u*u, b = 3*u*u*t, c = 3*u*t*t, d = t*t*t;\n        return { x: a*P0.x + b*P1.x + c*P2.x + d*P3.x, y: a*P0.y + b*P1.y + c*P2.y + d*P3.y };\n      }\n      var head = traveling ? bez(e) : P3;\n\n      ctx.globalCompositeOperation = 'lighter';\n\n      // comet tail: dense overlapping discs along the curve (a segmented\n      // stroke reads as a dotted line)\n      var tailAlpha = fadeIn * (1 - twk);\n      var tailSpan = 0.30 * (1 - twk);\n      if (tailSpan > 0.001) {\n        var K = 56;\n        for (var j = 0; j <= K; j++) {\n          var s = e - tailSpan + (j / K) * tailSpan;\n          if (s < 0) continue;\n          var q = bez(s), f = j / K;\n          ctx.fillStyle = 'rgba(232,240,255,' + (0.30 * f * f * tailAlpha) + ')';\n          ctx.beginPath(); ctx.arc(q.x, q.y, 0.7 + 3.1 * f, 0, Math.PI * 2); ctx.fill();\n        }\n      }\n\n      if (traveling) {\n        ctx.globalAlpha = fadeIn;\n        var hg = ctx.createRadialGradient(head.x, head.y, 0, head.x, head.y, 15);\n        hg.addColorStop(0, 'rgba(255,255,255,1)'); hg.addColorStop(1, 'rgba(255,255,255,0)');\n        ctx.fillStyle = hg; ctx.beginPath(); ctx.arc(head.x, head.y, 15, 0, Math.PI * 2); ctx.fill();\n      } else {\n        var cx = P3.x, cy = P3.y, av = 1 - twk, grow = 1 + twk * 1.6;\n        var core = 20 * (0.7 + twk * 0.6);\n        var cg = ctx.createRadialGradient(cx, cy, 0, cx, cy, core);\n        cg.addColorStop(0, 'rgba(255,255,255,' + av + ')'); cg.addColorStop(1, 'rgba(255,255,255,0)');\n        ctx.fillStyle = cg; ctx.beginPath(); ctx.arc(cx, cy, core, 0, Math.PI * 2); ctx.fill();\n        var fl = 26 * grow;\n        ctx.lineCap = 'round';\n        ctx.strokeStyle = 'rgba(255,255,255,' + (av * 0.9) + ')'; ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.moveTo(cx - fl, cy); ctx.lineTo(cx + fl, cy);\n        ctx.moveTo(cx, cy - fl); ctx.lineTo(cx, cy + fl);\n        ctx.stroke();\n        var fd = fl * 0.55;\n        ctx.strokeStyle = 'rgba(255,255,255,' + (av * 0.4) + ')';\n        ctx.beginPath();\n        ctx.moveTo(cx - fd, cy - fd); ctx.lineTo(cx + fd, cy + fd);\n        ctx.moveTo(cx - fd, cy + fd); ctx.lineTo(cx + fd, cy - fd);\n        ctx.stroke();\n      }\n\n      ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';\n      if (te >= SHIMMER + TWINKLE) { spawnDrips(); phase = 'melt'; meltAt = now; }\n\n    } else if (phase === 'melt') {\n      var el = (now - meltAt) / 1000;\n      var meltP = Math.min(1, el / (ONSET / 1000));\n      var front = (LY + SPLIT_PX) - meltP * SPLIT_PX;\n\n      drawIcon(1);\n      var feather = 30;\n      var grad = ctx.createLinearGradient(0, front - feather, 0, front);\n      grad.addColorStop(0, 'rgba(0,0,0,0)'); grad.addColorStop(1, 'rgba(0,0,0,1)');\n      ctx.globalCompositeOperation = 'destination-out';\n      ctx.fillStyle = grad; ctx.fillRect(LX, front - feather, LOGO, (LY + SPLIT_PX) - (front - feather));\n      ctx.globalCompositeOperation = 'source-over';\n\n      var wordAlpha = Math.max(0, 1 - el / (WORD_FADE / 1000));\n      drawWord(wordAlpha);\n\n      var falling = 0;\n      ctx.lineCap = 'round'; ctx.lineWidth = DRIP_WIDTH;\n      for (var k = 0; k < parts.length; k++) {\n        var p = parts[k];\n        if (el <= p.delay) continue;\n        p.vy += p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt;\n        if (p.y > H + 60) continue;   // fully past the bottom fade zone\n        falling++;\n        var len = Math.max(10, Math.min(TRAIL_MAX, p.vy * 0.07));\n        var ramp = Math.min(1, (el - p.delay) / 0.12);   // ease drips in so they don't pop as dots\n        ctx.globalAlpha = ramp * Math.max(0, Math.min(1, (H + 40 - p.y) / 130));\n        ctx.strokeStyle = p.color;\n        ctx.beginPath(); ctx.moveTo(p.x, p.y - len); ctx.lineTo(p.x, p.y); ctx.stroke();\n      }\n      ctx.globalAlpha = 1;\n\n      if ((meltP >= 1 && falling === 0 && wordAlpha <= 0) || el > MELT_MS / 1000) { phase = 'done'; finish(); }\n    }\n\n    if (phase !== 'done') raf = requestAnimationFrame(frame);\n  }\n\n  img.onload = function () {\n    try { buildLayers(); sampleLogo(); }\n    catch (e) { finish(); return; }   // e.g. pixel access blocked → skip to game splash\n    t0 = performance.now(); last = t0; phase = 'in';\n    raf = requestAnimationFrame(frame);\n  };\n  img.onerror = function () { finish(); };   // never block boot if the image fails\n  img.src = window.LOGO_SRC;\n\n  // hard safety: if anything stalls, hand off anyway\n  setTimeout(finish, 8000);\n})();\n</script>\n</body>\n</html>\n";
